"use strict";

const ADD_WASM_BYTES = new Uint8Array([
  0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
  0x01, 0x07, 0x01, 0x60, 0x02, 0x7f, 0x7f, 0x01,
  0x7f, 0x03, 0x02, 0x01, 0x00, 0x07, 0x07, 0x01,
  0x03, 0x61, 0x64, 0x64, 0x00, 0x00, 0x0a, 0x09,
  0x01, 0x07, 0x00, 0x20, 0x00, 0x20, 0x01, 0x6a,
  0x0b,
]);

module.exports = async function wasmWorkerFallbackProbe() {
  let workerPolicyKnown = false;
  try {
    const workerThreads = require("worker_threads");
    workerPolicyKnown = typeof workerThreads.Worker === "function";
  } catch (error) {
    workerPolicyKnown = String(error && error.code || "").length > 0;
  }
  const instance = await WebAssembly.instantiate(ADD_WASM_BYTES);
  const value = instance.instance.exports.add(4, 5);
  return {
    value,
    summary: `worker-wasm:fallback/${value}/${workerPolicyKnown}`,
  };
};
